IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiDcrAdmissionV3') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0x9e167c361af8dc892470e014f716cb1523e688d6d050e128d0f02c15c84f90f0) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiDcrAdmissionV3')) THROW 59700,'C2 module drift: AiDcrAdmissionV3.',1;
