IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiDcrStatusV3') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0x575c1952ea95b7f6c62552c1e3d9ce244f971999c841edf36c25928553a6329e) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiDcrStatusV3')) THROW 59700,'C2 module drift: AiDcrStatusV3.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiDcrCompatibilityV3') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0xe4e513076ca511df78ef4980a08432de4734c55b31c98fc21986eab34b41122a) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiDcrCompatibilityV3')) THROW 59700,'C2 module drift: AiDcrCompatibilityV3.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiCimdImmutablePublicationV1') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0xdbe68cabe55d42922f3f3e01458b43395c7b61487410a48af62529a875c36d7a) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiCimdImmutablePublicationV1')) THROW 59700,'C2 module drift: AiCimdImmutablePublicationV1.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiDcrRegisterApplicationV3') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0xbefcd22637dcc9967298d6085690a2f8a3eb196486ef36aa7bf8a6ec4f84f0de) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiDcrRegisterApplicationV3')) THROW 59700,'C2 module drift: AiDcrRegisterApplicationV3.',1;
DECLARE @C2Objects table(Name sysname PRIMARY KEY); INSERT @C2Objects VALUES (N'AiDcrAdmissionV3'),(N'AiDcrCompatibilityV3'),(N'AiDcrControlV3'),(N'AiDcrExpirePendingV3'),(N'AiDcrRateV3'),(N'AiDcrRegisterApplicationV3'),(N'AiDcrStatusV3');
DECLARE @C2Graph nvarchar(max)=N'';
SET @C2Graph=@C2Graph+(SELECT CONCAT(o.name,N':',o.type,N':',o.principal_id,N':',m.execute_as_principal_id,N':',m.uses_ansi_nulls,N':',m.uses_quoted_identifier,N':',m.definition,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.schema_id=SCHEMA_ID(N'dbo') AND o.name IN(SELECT Name FROM @C2Objects) ORDER BY o.name FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C2Graph=@C2Graph+(SELECT CONCAT(OBJECT_NAME(c.object_id),N':',c.column_id,N':',c.name,N':',c.user_type_id,N':',c.max_length,N':',c.is_nullable,N':',c.is_identity,N':',c.collation_name,N';') AS [text()] FROM sys.columns c WHERE OBJECT_NAME(c.object_id) IN(SELECT Name FROM @C2Objects) ORDER BY c.object_id,c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C2Graph=@C2Graph+(SELECT CONCAT(OBJECT_NAME(o.parent_object_id),N':',o.name,N':',o.type,N':',ch.definition,N':',ch.is_disabled,N':',ch.is_not_trusted,N':',dc.definition,N':',fk.referenced_object_id,N':',fk.is_disabled,N':',fk.is_not_trusted,N':',fk.delete_referential_action,N':',fk.update_referential_action,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.check_constraints ch ON ch.object_id=o.object_id LEFT JOIN sys.default_constraints dc ON dc.object_id=o.object_id LEFT JOIN sys.foreign_keys fk ON fk.object_id=o.object_id WHERE OBJECT_NAME(o.parent_object_id) IN(SELECT Name FROM @C2Objects) ORDER BY o.object_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C2Graph=@C2Graph+COALESCE((SELECT CONCAT(f.constraint_object_id,N':',f.constraint_column_id,N':',f.parent_column_id,N':',f.referenced_column_id,N';') AS [text()] FROM sys.foreign_key_columns f WHERE OBJECT_NAME(f.parent_object_id) IN(SELECT Name FROM @C2Objects) ORDER BY f.constraint_object_id,f.constraint_column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),N'');
SET @C2Graph=@C2Graph+(SELECT CONCAT(i.object_id,N':',i.name,N':',i.is_unique,N':',i.is_disabled,N':',i.filter_definition,N':',c.column_id,N':',c.key_ordinal,N':',c.is_included_column,N';') AS [text()] FROM sys.indexes i JOIN sys.index_columns c ON c.object_id=i.object_id AND c.index_id=i.index_id WHERE OBJECT_NAME(i.object_id) IN(SELECT Name FROM @C2Objects) ORDER BY i.object_id,i.index_id,c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C2Graph=@C2Graph+COALESCE((SELECT CONCAT(object_id,N':',column_id,N':',definition,N';') AS [text()] FROM sys.computed_columns WHERE OBJECT_NAME(object_id) IN(SELECT Name FROM @C2Objects) ORDER BY object_id,column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),N'');
SET @C2Graph=@C2Graph+(SELECT CONCAT(p.class,N':',p.major_id,N':',p.minor_id,N':',p.grantee_principal_id,N':',p.grantor_principal_id,N':',p.permission_name,N':',p.state,N';') AS [text()] FROM sys.database_permissions p WHERE p.class=1 AND OBJECT_NAME(p.major_id) IN(SELECT Name FROM @C2Objects) OR p.grantee_principal_id=DATABASE_PRINCIPAL_ID(N'AiDcrEndpointV3') ORDER BY p.class,p.major_id,p.minor_id,p.grantee_principal_id,p.permission_name FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
DECLARE @C2Seal binary(32); SELECT @C2Seal=CONVERT(binary(32),value) FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.AiDcrCompatibilityV3') AND name=N'DcrEndpointV3.Catalog';
IF @C2Seal IS NULL OR @C2Graph IS NULL OR HASHBYTES('SHA2_256',@C2Graph)<>@C2Seal THROW 59700,'C2 catalog drift; never refresh receipts.',1;
IF NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'dbo.AiDcrImmutableMetadataV2') AND is_disabled=0 AND is_instead_of_trigger=0) THROW 59700,'C2 retention trigger disabled.',1;
IF EXISTS(SELECT 1 FROM sys.triggers WHERE OBJECT_NAME(parent_id) IN(N'AiDcrControlV3',N'AiDcrRateV3'))
 OR EXISTS(SELECT 1 FROM sys.security_predicates WHERE OBJECT_NAME(target_object_id) IN(N'AiDcrControlV3',N'AiDcrRateV3')) THROW 59700,'Unexpected C2 table authority.',1;
DECLARE @C2Members table(Id int PRIMARY KEY); INSERT @C2Members SELECT member_principal_id FROM sys.database_role_members WHERE role_principal_id=DATABASE_PRINCIPAL_ID(N'AiDcrEndpointV3');
IF NOT EXISTS(SELECT 1 FROM sys.database_principals WHERE name=N'AiDcrEndpointV3' AND type='R' AND owning_principal_id=1)
 OR EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id=DATABASE_PRINCIPAL_ID(N'AiDcrEndpointV3'))
 OR EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN(SELECT Id FROM @C2Members) AND role_principal_id<>DATABASE_PRINCIPAL_ID(N'AiDcrEndpointV3'))
 OR EXISTS(SELECT 1 FROM sys.database_principals WHERE principal_id IN(SELECT Id FROM @C2Members) AND (type<>'S' OR principal_id<=4 OR owning_principal_id IS NOT NULL))
 OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE grantee_principal_id IN(SELECT Id FROM @C2Members) AND NOT(class=0 AND permission_name='CONNECT' AND state='G'))
 OR EXISTS(SELECT 1 FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE COALESCE(o.principal_id,s.principal_id) IN(SELECT Id FROM @C2Members))
 THROW 59700,'C2 endpoint identity drift.',1;
 DECLARE @C2IdentityMembers table(Id int PRIMARY KEY,RoleId int,Sid varbinary(85),AuthenticationType int);
 INSERT @C2IdentityMembers SELECT p.principal_id,r.role_principal_id,p.sid,p.authentication_type
 FROM sys.database_role_members r JOIN sys.database_principals p ON p.principal_id=r.member_principal_id
 WHERE r.role_principal_id IN(DATABASE_PRINCIPAL_ID(N'AiDcrEndpointV3'));
 IF EXISTS(SELECT 1 FROM @C2IdentityMembers a JOIN sys.database_principals p ON p.principal_id=a.Id WHERE p.type<>'S' OR p.principal_id<=4)
 OR EXISTS(SELECT 1 FROM sys.database_role_members r JOIN @C2IdentityMembers a ON a.Id=r.member_principal_id WHERE r.role_principal_id<>a.RoleId)
 OR EXISTS(SELECT 1 FROM sys.database_permissions p JOIN @C2IdentityMembers a ON p.grantee_principal_id=a.Id WHERE NOT(p.class=0 AND p.permission_name='CONNECT' AND p.state='G'))
 THROW 59310,'Registry member token/direct authority drift.',1;
 DECLARE @C2IdentityTokens table(Id int PRIMARY KEY);
 INSERT @C2IdentityTokens SELECT Id FROM @C2IdentityMembers;
 INSERT @C2IdentityTokens VALUES(DATABASE_PRINCIPAL_ID(N'AiDcrEndpointV3'));
 IF EXISTS(SELECT 1 FROM sys.schemas WHERE principal_id IN(SELECT Id FROM @C2IdentityTokens))
 OR EXISTS(SELECT 1 FROM sys.objects WHERE principal_id IN(SELECT Id FROM @C2IdentityTokens))
 OR EXISTS(SELECT 1 FROM sys.database_principals WHERE owning_principal_id IN(SELECT Id FROM @C2IdentityTokens))
 OR EXISTS(SELECT 1 FROM sys.types WHERE is_user_defined=1 AND principal_id IN(SELECT Id FROM @C2IdentityTokens))
 OR EXISTS(SELECT 1 FROM sys.certificates WHERE principal_id IN(SELECT Id FROM @C2IdentityTokens))
 OR EXISTS(SELECT 1 FROM sys.asymmetric_keys WHERE principal_id IN(SELECT Id FROM @C2IdentityTokens))
 OR EXISTS(SELECT 1 FROM sys.assemblies WHERE principal_id IN(SELECT Id FROM @C2IdentityTokens))
 THROW 59310,'Registry securable ownership bridge.',1;

 DECLARE @C2IdentityEdition int=CONVERT(int,SERVERPROPERTY('EngineEdition'));
 IF @C2IdentityEdition NOT IN(2,3,4,5,8) OR @C2IdentityEdition IS NULL THROW 59310,'Unknown registry platform.',1;
 IF @C2IdentityEdition=5 BEGIN
  IF EXISTS(SELECT 1 FROM @C2IdentityMembers WHERE AuthenticationType<>2) THROW 59310,'Contained registry SQL users required.',1;
 END ELSE BEGIN
  IF EXISTS(SELECT 1 FROM @C2IdentityMembers WHERE AuthenticationType<>1) THROW 59310,'Mapped registry SQL users required.',1;
  IF ISNULL(HAS_PERMS_BY_NAME(NULL,NULL,'VIEW ANY DEFINITION'),0)<>1 OR ISNULL(HAS_PERMS_BY_NAME(NULL,NULL,'VIEW ANY DATABASE'),0)<>1
  THROW 59310,'Registry server catalog visibility required.',1;
  /* This branch is never issued on Azure SQL Database. */
  DECLARE @C2IdentityServerCheck nvarchar(max)=N'
  IF EXISTS(SELECT 1 FROM sys.database_role_members r JOIN sys.database_principals u ON u.principal_id=r.member_principal_id LEFT JOIN sys.server_principals s ON s.sid=u.sid
   WHERE r.role_principal_id IN(DATABASE_PRINCIPAL_ID(N''AiDcrEndpointV3'')) AND (s.type<>''S'' OR s.is_disabled=1 OR s.principal_id IS NULL))
  OR EXISTS(SELECT 1 FROM sys.server_role_members r JOIN sys.server_principals s ON s.principal_id=r.member_principal_id JOIN sys.database_principals u ON u.sid=s.sid JOIN sys.database_role_members d ON d.member_principal_id=u.principal_id
   WHERE d.role_principal_id IN(DATABASE_PRINCIPAL_ID(N''AiDcrEndpointV3'')))
  OR EXISTS(SELECT 1 FROM sys.server_permissions p JOIN sys.server_principals s ON s.principal_id=p.grantee_principal_id JOIN sys.database_principals u ON u.sid=s.sid JOIN sys.database_role_members d ON d.member_principal_id=u.principal_id
   WHERE d.role_principal_id IN(DATABASE_PRINCIPAL_ID(N''AiDcrEndpointV3'')) AND p.state IN(''G'',''W'') AND NOT(p.class=100 AND p.state=''G'' AND p.permission_name IN(''CONNECT SQL'',''VIEW ANY DATABASE'')))
  THROW 59310,''Registry SQL login server authority drift.'',1;';
  EXEC(@C2IdentityServerCheck);
 END;


/* Reviewed C1 registry successor; validated delta, unchanged historical receipts. */
SET NOCOUNT ON;
IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID(N'dbo.AiExternalCompatibilityV2') AND name=N'DcrCompatV2.Source' AND CONVERT(binary(32),value)=0xb1bb5f12c138d59136da3d31ddb7dcaf1113d82375a12502a9f4bbe0d272c25d) THROW 59600,'Reviewed C1 successor required; no fallback.',1;
DECLARE @C1ConstraintId int,@C1ConstraintDefinition nvarchar(max),@C1HistoricalHash binary(32),@C1CatalogHash binary(32);
SELECT @C1ConstraintId=TRY_CONVERT(int,value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID(N'dbo.AiExternalCompatibilityV2') AND name=N'DcrCompatV2.OldConstraintId';
SELECT @C1ConstraintDefinition=CONVERT(nvarchar(max),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID(N'dbo.AiExternalCompatibilityV2') AND name=N'DcrCompatV2.OldConstraintDefinition';
SELECT @C1HistoricalHash=CONVERT(binary(32),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID(N'dbo.AiExternalCompatibilityV2') AND name=N'DcrCompatV2.Historical';
SELECT @C1CatalogHash=CONVERT(binary(32),value) FROM sys.extended_properties WHERE class=1 AND major_id=OBJECT_ID(N'dbo.AiExternalCompatibilityV2') AND name=N'DcrCompatV2.Catalog';

IF @C1ConstraintId IS NULL THROW 59600,'Incomplete C1 receipt: predecessor constraint ID.',1;
IF @C1ConstraintDefinition IS NULL THROW 59600,'Incomplete C1 receipt: predecessor constraint definition.',1;
IF @C1HistoricalHash IS NULL THROW 59600,'Incomplete C1 receipt: historical snapshot.',1;
IF @C1CatalogHash IS NULL THROW 59600,'Incomplete C1 receipt: catalog seal.',1;
